using System.Runtime.CompilerServices;
using System.Text.Json;
using System.Threading.Channels;

namespace DotReticulum.Core.Tests;

// Generated by actual RNS a29bfb51c468945c96a1ee22cae0114e993e2391; see GenerateParity8PhyVectors.py.
[Trait("Category", "Unit")]
public sealed class Parity8PhyTests
{
    private sealed class ReportingInterface : IPacketInterfacePhysicalLayer
    {
        private readonly Channel<ReceivedFrame> _frames = Channel.CreateBounded<ReceivedFrame>(8);
        public ValueTask Inject(byte[] data, PacketPhysicalLayer phy) => _frames.Writer.WriteAsync(new(data, phy));
        public ValueTask StartAsync(CancellationToken cancellationToken) => ValueTask.CompletedTask;
        public async IAsyncEnumerable<ReceivedFrame> ReceiveFramesAsync([EnumeratorCancellation] CancellationToken cancellationToken)
        {
            await foreach (var frame in _frames.Reader.ReadAllAsync(cancellationToken)) yield return frame;
        }
        public IAsyncEnumerable<ReadOnlyMemory<byte>> ReceiveAsync(CancellationToken cancellationToken) =>
            throw new InvalidOperationException("Manager must use the atomic metadata boundary.");
        public ValueTask SendAsync(ReadOnlyMemory<byte> packet, CancellationToken cancellationToken) => ValueTask.CompletedTask;
        public ValueTask DisposeAsync() { _frames.Writer.TryComplete(); return ValueTask.CompletedTask; }
    }

    private static JsonDocument Vectors() => JsonDocument.Parse(File.ReadAllText(
        Path.Combine(AppContext.BaseDirectory, "Fixtures", "Parity8PhyVectors.json")));
    private static double? Number(JsonElement value) => value.ValueKind == JsonValueKind.Null ? null : value.GetDouble();
    private static PacketPhysicalLayer Phy(JsonElement value) => new(Number(value.GetProperty("rssi")),
        Number(value.GetProperty("snr")), Number(value.GetProperty("quality")));
    private static byte[] Raw(JsonElement value) => Convert.FromHexString(value.GetProperty("raw").GetString()!);
    private static async Task<ReceivedPacket> Next(IAsyncEnumerator<ReceivedPacket> reader)
    {
        Assert.True(await reader.MoveNextAsync().AsTask().WaitAsync(TimeSpan.FromSeconds(5)));
        return reader.Current;
    }

    [Fact]
    public async Task InterleavedPeersKeepAtomicSnapshotsWithBackpressureAndNoSubscribers()
    {
        using var vectors = Vectors();
        var values = vectors.RootElement.GetProperty("packets").EnumerateArray().ToArray();
        var first = new ReportingInterface();
        var second = new ReportingInterface();
        await using var manager = new PacketInterfaceManager([first, second], channelCapacity: 1);
        await manager.StartAsync();
        await using var reader = manager.ReceiveWithSourceAsync().GetAsyncEnumerator();
        await first.Inject(Raw(values[0]), Phy(values[0]));
        var a = await Next(reader);
        await second.Inject(Raw(values[1]), Phy(values[1]));
        await first.Inject(Raw(values[2]), default);
        var remaining = new[] { await Next(reader), await Next(reader) };
        Assert.Same(first, a.Source);
        Assert.Equal(Phy(values[0]), a.Packet.PhysicalLayer);
        Assert.Equal(values[0].GetProperty("hash").GetString(), Convert.ToHexStringLower(a.Packet.CalculateHash()));
        Assert.Equal(Phy(values[1]), Assert.Single(remaining, p => ReferenceEquals(p.Source, second)).Packet.PhysicalLayer);
        Assert.Equal(default, Assert.Single(remaining, p => ReferenceEquals(p.Source, first)).Packet.PhysicalLayer);
        Assert.Equal(Phy(values[0]), manager.GetPacketPhysicalLayer(a.Packet.CalculateHash()));
        Assert.Equal(Raw(values[0]), a.Packet.ToArray());
    }

    [Fact]
    public async Task CacheMatchesReferencePerFieldFifoDuplicateLookupAndEviction()
    {
        using var vectors = Vectors();
        var root = vectors.RootElement;
        var values = root.GetProperty("packets").EnumerateArray().ToArray();
        var iface = new ReportingInterface();
        await using var manager = new PacketInterfaceManager([iface]);
        await manager.StartAsync();
        await using var reader = manager.ReceiveWithSourceAsync().GetAsyncEnumerator();
        await iface.Inject(Raw(values[0]), Phy(values[0]));
        var original = (await Next(reader)).Packet;
        await iface.Inject(Raw(values[1]), Phy(values[1]));
        await Next(reader);
        var duplicate = root.GetProperty("duplicate");
        await iface.Inject(Raw(values[0]), new(duplicate.GetProperty("direct").GetDouble()));
        Assert.Equal(duplicate.GetProperty("direct").GetDouble(), (await Next(reader)).Packet.PhysicalLayer.Rssi);
        Assert.Equal(duplicate.GetProperty("cached").GetDouble(), manager.GetPacketPhysicalLayer(original.CalculateHash()).Rssi);
        var eviction = root.GetProperty("eviction");
        for (var i = 3; i < eviction.GetProperty("maximum").GetInt32() + 3; i++)
        {
            var packet = Packet.Create(PacketType.Data, DestinationType.Plain, new byte[16], BitConverter.GetBytes(i));
            await iface.Inject(packet.ToArray(), new(-100));
            await Next(reader);
        }
        Assert.Equal(Phy(eviction), manager.GetPacketPhysicalLayer(original.CalculateHash()));
        Assert.Equal(Phy(values[0]), original.PhysicalLayer);
        Assert.Throws<ArgumentException>(() => manager.GetPacketPhysicalLayer(new byte[16]));
        await using var fresh = new PacketInterfaceManager([]);
        Assert.Equal(default, fresh.GetPacketPhysicalLayer(original.CalculateHash()));
    }

    [Fact]
    public async Task MalformedFramesCannotPopulateCacheAndSharedLookupIsExplicitAndCancellable()
    {
        var iface = new ReportingInterface();
        await using var manager = new PacketInterfaceManager([iface]);
        await manager.StartAsync();
        await using var reader = manager.ReceiveWithSourceAsync().GetAsyncEnumerator();
        await iface.Inject([1], new(-99));
        var outgoing = Packet.Create(PacketType.Data, DestinationType.Plain, new byte[16], new byte[] { 3 });
        await iface.Inject(outgoing.ToArray(), default);
        var packet = (await Next(reader)).Packet;
        Assert.Equal(default, packet.PhysicalLayer);
        Assert.Equal(default, manager.GetPacketPhysicalLayer(packet.CalculateHash()));
        var calls = 0;
        manager.SharedPhysicalLayerLookup = (hash, token) =>
        {
            calls++;
            Assert.Equal(packet.CalculateHash(), hash);
            token.ThrowIfCancellationRequested();
            return ValueTask.FromResult(new PacketPhysicalLayer(-82, 2, 73));
        };
        using var cancelled = new CancellationTokenSource();
        cancelled.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => manager.ResolvePacketPhysicalLayerAsync(packet, cancelled.Token).AsTask());
        Assert.Equal(0, calls);
        Assert.Equal(new(-82, 2, 73), await manager.ResolvePacketPhysicalLayerAsync(packet));
        Assert.Equal(new(-82, 2, 73), await manager.ResolvePacketPhysicalLayerAsync(packet));
        Assert.Equal(1, calls);
        Assert.Equal(default, outgoing.PhysicalLayer);
        Assert.Equal(default, manager.GetPacketPhysicalLayer(packet.CalculateHash()));
    }
}
